mapper.select:
SELECT s.id, s.spu_id, p.name AS spu_name, s.name, s.price, s.stock, s.status FROM product_sku s LEFT JOIN product_spu p ON s.spu_id = p.id WHERE s.deleted = 0
AND s.name LIKE CONCAT('%', #{query.name}, '%')
AND s.spu_id = #{query.spuId}
AND s.status = #{query.status}
ORDER BY s.id DESC

mapper.update:
update `product_sku`
set stock = stock - #{quantity}
where id = #{skuId}
  and stock >= #{quantity}

update `product_sku`
set stock = stock + #{quantity}
where id = #{skuId}
